import fs from 'fs';
import path from 'path';
import chalk from 'chalk';
import { execFileSync } from 'child_process';
import { ROOT_FILES, MODULE_ROOT, moduleDirs } from '../core/project-layout.js';
import { findLegacyEntries } from '../core/workdir.js';
import { success, info, fatal } from '../utils/logger.js';

// `tgcloud upgrade`: move root-level schema.js and module directories into the
// module root. `.tgcloud/` is keyed by module path, so it stays valid as-is.

function isDir(p) {
  try { return fs.statSync(p).isDirectory(); } catch { return false; }
}

function git(args) {
  return execFileSync('git', args, { stdio: ['ignore', 'pipe', 'ignore'], encoding: 'utf-8' });
}

function insideGitWorkTree() {
  try { return git(['rev-parse', '--is-inside-work-tree']).trim() === 'true'; } catch { return false; }
}

// Whether git tracks anything under the path. `git mv` fails for a source with
// nothing tracked, so those get a plain rename.
function isTracked(p) {
  try { return git(['ls-files', '--', p]).trim() !== ''; } catch { return false; }
}

// Every root file and module directory at the project root moves to the same
// name under the module root.
function planMoves() {
  const moves = [];
  for (const f of ROOT_FILES) {
    if (fs.existsSync(f) && fs.statSync(f).isFile()) moves.push({ from: f, to: path.join(MODULE_ROOT, f) });
  }
  for (const d of moduleDirs()) {
    if (isDir(d)) moves.push({ from: d, to: path.join(MODULE_ROOT, d) });
  }
  return moves;
}

export function registerUpgrade(program) {
  program
    .command('upgrade')
    .description(`Move a pre-0.2.0 project layout (modules at the root) into ${MODULE_ROOT}/`)
    .option('--dry-run', 'Print the planned moves without touching anything')
    .action((options) => {
      // The working directory is already the project root.
      if (!fs.existsSync('.tgcloud')) {
        fatal('Not a tgcloud project (no .tgcloud/ found here or in any parent directory).');
      }

      const legacy = findLegacyEntries();
      const moves = planMoves();

      if (!legacy.length) {
        const populated = [...ROOT_FILES, ...moduleDirs()].some((n) => fs.existsSync(path.join(MODULE_ROOT, n)));
        if (populated) {
          info(`This project already uses ${MODULE_ROOT}/. Nothing to do.`);
          // Root-level directories next to a populated module root are not moved.
          if (moves.length) {
            info(chalk.dim(`  (Root-level ${moves.map((m) => m.from + '/').join(', ')} left untouched — not tgcloud modules.)`));
          }
        } else {
          info(`Nothing to upgrade: no tgcloud modules at the project root. Run "tgcloud init" to scaffold ${MODULE_ROOT}/.`);
          if (moves.length) {
            info(chalk.dim(`  (Root-level ${moves.map((m) => m.from + '/').join(', ')} left untouched — this project has never synced modules, so it is not treated as a pre-0.2.0 layout.)`));
          }
        }
        return;
      }

      // Never merge into an existing, non-empty module root.
      if (isDir(MODULE_ROOT) && fs.readdirSync(MODULE_ROOT).length) {
        fatal(
          `${MODULE_ROOT}/ already exists and is not empty. ` +
          `Move ${legacy.join(', ')} into it by hand, or empty it and rerun.`
        );
      }
      const occupied = moves.filter((m) => fs.existsSync(m.to)).map((m) => m.to);
      if (occupied.length) {
        fatal(`Cannot upgrade: ${occupied.join(', ')} already exist${occupied.length === 1 ? 's' : ''}.`);
      }

      const useGit = insideGitWorkTree();
      // Labels are computed up front: after the move the source no longer exists.
      for (const m of moves) {
        const slash = isDir(m.from) ? '/' : '';
        m.label = `${m.from}${slash} → ${m.to}${slash}`;
      }

      if (options.dryRun) {
        info(`Would move into ${MODULE_ROOT}/:`);
        for (const m of moves) {
          const via = useGit && isTracked(m.from) ? 'git mv' : 'rename';
          info(`  ${m.label}  ${chalk.dim(`(${via})`)}`);
        }
        info(chalk.dim('\nDry run — nothing was changed.'));
        return;
      }

      info(`Moving modules into ${MODULE_ROOT}/...`);
      fs.mkdirSync(MODULE_ROOT, { recursive: true });
      for (const m of moves) {
        if (useGit && isTracked(m.from)) {
          try {
            execFileSync('git', ['mv', '--', m.from, m.to], { stdio: 'ignore' });
          } catch {
            fatal(`git mv ${m.from} ${m.to} failed. Fix the repository state and rerun.`);
          }
        } else {
          fs.renameSync(m.from, m.to);
        }
        success(m.label);
      }

      info(`\nDone. .tgcloud/ (snapshot, state, credentials) is unchanged — "tgcloud status" should be clean.`);
      if (useGit) info(`Review with "git status" and commit the move.`);
      info(chalk.dim(`If you kept the scaffolded AGENTS.md, update its layout table to the new paths.`));
    });
}
